import React, { useState, useEffect } from 'react';
import { Link } from 'gatsby';
import { CSSTransition, TransitionGroup } from 'react-transition-group';
import PropTypes from 'prop-types';
import { Layout } from '@components';
import styled, { keyframes } from 'styled-components';
import { theme, mixins, media, Main } from '@styles';
const { fonts, navDelay } = theme;

const glitch = keyframes`
  0% {
    text-shadow: 0.05em 0 0 rgba(255, 0, 0, 0.75),
                 -0.05em -0.025em 0 rgba(0, 255, 0, 0.75),
                 -0.025em 0.05em 0 rgba(0, 0, 255, 0.75);
  }
  14% {
    text-shadow: 0.05em 0 0 rgba(255, 0, 0, 0.75),
                 -0.05em -0.025em 0 rgba(0, 255, 0, 0.75),
                 -0.025em 0.05em 0 rgba(0, 0, 255, 0.75);
  }
  15% {
    text-shadow: -0.05em -0.025em 0 rgba(255, 0, 0, 0.75),
                 0.025em 0.025em 0 rgba(0, 255, 0, 0.75),
                 -0.05em -0.05em 0 rgba(0, 0, 255, 0.75);
  }
  49% {
    text-shadow: -0.05em -0.025em 0 rgba(255, 0, 0, 0.75),
                 0.025em 0.025em 0 rgba(0, 255, 0, 0.75),
                 -0.05em -0.05em 0 rgba(0, 0, 255, 0.75);
  }
  50% {
    text-shadow: 0.025em 0.05em 0 rgba(255, 0, 0, 0.75),
                 0.05em 0 0 rgba(0, 255, 0, 0.75),
                 0 -0.05em 0 rgba(0, 0, 255, 0.75);
  }
  99% {
    text-shadow: 0.025em 0.05em 0 rgba(255, 0, 0, 0.75),
                 0.05em 0 0 rgba(0, 255, 0, 0.75),
                 0 -0.05em 0 rgba(0, 0, 255, 0.75);
  }
  100% {
    text-shadow: -0.025em 0 0 rgba(255, 0, 0, 0.75),
                 -0.025em -0.025em 0 rgba(0, 255, 0, 0.75),
                 -0.025em -0.05em 0 rgba(0, 0, 255, 0.75);
  }
`;

const StyledMainContainer = styled(Main)`
  ${mixins.flexCenter};
  flex-direction: column;
  text-align: center;
  padding: 0 20px;
`;

const StyledTitle = styled.h1`
  color: var(--color-accent);
  font-family: ${fonts.SFMono};
  font-size: 12vw;
  line-height: 1;
  margin-bottom: 10px;
  animation: ${glitch} 2s infinite;
  ${media.bigDesktop`font-size: 200px;`}
  ${media.phablet`font-size: 120px;`};

  @media (prefers-reduced-motion: reduce) {
    animation: none;
  }
`;

const StyledSubtitle = styled.h2`
  font-size: 3vw;
  font-weight: 400;
  color: var(--color-text-lightest);
  ${media.bigDesktop`font-size: 50px;`};
  ${media.phablet`font-size: 30px;`};
`;

const StyledDescription = styled.p`
  color: var(--color-text-light);
  font-size: ${theme.fontSizes.lg};
  max-width: 500px;
  margin: 20px 0 40px;
  ${media.phablet`font-size: ${theme.fontSizes.md};`};
`;

const StyledButtonContainer = styled.div`
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
  justify-content: center;
`;

const StyledHomeButton = styled(Link)`
  ${mixins.bigButton};
`;

const StyledSecondaryButton = styled(Link)`
  ${mixins.smallButton};
  padding: 1rem 1.5rem;
`;

const StyledQuickLinks = styled.div`
  margin-top: 60px;
  text-align: center;
`;

const StyledQuickLinksTitle = styled.h3`
  color: var(--color-text-light);
  font-family: ${fonts.SFMono};
  font-size: ${theme.fontSizes.sm};
  margin-bottom: 20px;
`;

const StyledQuickLinksList = styled.ul`
  display: flex;
  gap: 30px;
  list-style: none;
  padding: 0;
  margin: 0;
  flex-wrap: wrap;
  justify-content: center;

  li a {
    color: var(--color-text);
    font-family: ${fonts.SFMono};
    font-size: ${theme.fontSizes.sm};

    &:hover {
      color: var(--color-accent);
    }
  }
`;

const NotFoundPage = ({ location }) => {
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    const timeout = setTimeout(() => setIsMounted(true), navDelay);
    return () => clearTimeout(timeout);
  }, []);

  const quickLinks = [
    { name: 'About', url: '/#about' },
    { name: 'Experience', url: '/#jobs' },
    { name: 'Projects', url: '/#projects' },
    { name: 'Contact', url: '/#contact' },
  ];

  return (
    <Layout location={location}>
      <TransitionGroup component={null}>
        {isMounted && (
          <CSSTransition timeout={500} classNames="fade">
            <StyledMainContainer className="fillHeight">
              <StyledTitle>404</StyledTitle>
              <StyledSubtitle>Page Not Found</StyledSubtitle>
              <StyledDescription>
                Oops! The page you're looking for doesn't exist or has been moved.
              </StyledDescription>
              <StyledButtonContainer>
                <StyledHomeButton to="/">Go Home</StyledHomeButton>
                <StyledSecondaryButton to="/#contact">Contact Me</StyledSecondaryButton>
              </StyledButtonContainer>
              <StyledQuickLinks>
                <StyledQuickLinksTitle>Or try one of these:</StyledQuickLinksTitle>
                <StyledQuickLinksList>
                  {quickLinks.map(({ name, url }, i) => (
                    <li key={i}>
                      <Link to={url}>{name}</Link>
                    </li>
                  ))}
                </StyledQuickLinksList>
              </StyledQuickLinks>
            </StyledMainContainer>
          </CSSTransition>
        )}
      </TransitionGroup>
    </Layout>
  );
};

NotFoundPage.propTypes = {
  location: PropTypes.object.isRequired,
};

export default NotFoundPage;
